fn mirror(a: &Option<Box<TreeNode>>, b: &Option<Box<TreeNode>>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => {
            x.val == y.val
                && mirror(&x.left, &y.right)
                && mirror(&x.right, &y.left)
        }
        _ => false,
    }
}

fn is_symmetric(root: &Option<Box<TreeNode>>) -> bool {
    match root {
        None => true,
        Some(node) => mirror(&node.left, &node.right),
    }
}

