fn depth(node: &Option<Box<TreeNode>>, best: &mut i32) -> i32 {
    match node {
        None => 0,
        Some(n) => {
            let left = depth(&n.left, best);
            let right = depth(&n.right, best);
            *best = (*best).max(left + right);
            1 + left.max(right)
        }
    }
}

fn diameter_of_binary_tree(root: &Option<Box<TreeNode>>) -> i32 {
    let mut best = 0;
    depth(root, &mut best);
    best
}

