fn height(node: &Option<Box<TreeNode>>) -> i32 {
    match node {
        None => 0,
        Some(n) => {
            let left = height(&n.left);
            let right = height(&n.right);
            if left < 0 || right < 0 || (left - right).abs() > 1 {
                -1
            } else {
                1 + left.max(right)
            }
        }
    }
}

fn is_balanced(root: &Option<Box<TreeNode>>) -> bool {
    height(root) >= 0
}

