fn has_path_sum(root: &Option<Box<TreeNode>>, target: i32) -> bool {
    match root {
        None => false,
        Some(node) => {
            if node.left.is_none() && node.right.is_none() {
                return node.val == target;
            }
            has_path_sum(&node.left, target - node.val)
                || has_path_sum(&node.right, target - node.val)
        }
    }
}

