fn lowest_common_ancestor<'a>(
    root: &'a Option<Box<TreeNode>>,
    p: i32,
    q: i32,
) -> Option<&'a TreeNode> {
    let mut current = root.as_deref();
    while let Some(node) = current {
        if p < node.val && q < node.val {
            current = node.left.as_deref();
        } else if p > node.val && q > node.val {
            current = node.right.as_deref();
        } else {
            return Some(node);
        }
    }
    None
}

fn search_insert(nums: &[i32], target: i32) -> usize {
    let mut lo = 0;
    let mut hi = nums.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if nums[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn two_sum_sorted(numbers: &[i32], target: i32) -> Vec<usize> {
    let mut left = 0;
    let mut right = numbers.len() - 1;
    while left < right {
        let total = numbers[left] + numbers[right];
        if total == target {
            return vec![left + 1, right + 1];
        } else if total < target {
            left += 1;
        } else {
            right -= 1;
        }
    }
    vec![]
}

fn length_of_longest_substring(s: &str) -> usize {
    use std::collections::HashMap;
    let mut last = HashMap::new();
    let mut start = 0;
    let mut best = 0;
    for (i, c) in s.chars().enumerate() {
        if let Some(&index) = last.get(&c) {
            if index >= start {
                start = index + 1;
            }
        }
        last.insert(c, i);
        best = best.max(i - start + 1);
    }
    best
}

fn max_area(height: &[i32]) -> i32 {
    let mut left = 0;
    let mut right = height.len() - 1;
    let mut best = 0;
    while left < right {
        best = best.max(height[left].min(height[right]) * (right - left) as i32);
        if height[left] < height[right] {
            left += 1;
        } else {
            right -= 1;
        }
    }
    best
}
